function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function load(){const data=await apiFetch('/operacoes/admin/stock');document.getElementById('rows').innerHTML=data.length?data.map(p=>`<tr><td>${esc(p.nome)}</td><td>${esc(p.fornecedor)}</td><td><input type="number" min="0" value="${p.stock}" onchange="setStock(${p.id},this.value)"></td><td>${p.stock<=0?'<span class="tag-alerta">Esgotado</span>':p.stock<10?'<span class="tag-alerta">Baixo</span>':'<span class="tag-ok">Disponível</span>'}</td><td>${(p.variantes||[]).map(v=>`<div style="margin:4px 0">${esc(v.valor)}: <input style="width:75px" type="number" min="0" value="${v.stock}" onchange="setVar(${v.id},this.value)"></div>`).join('')||'—'}</td></tr>`).join(''):'<tr><td colspan="5">Não existem produtos ativos.</td></tr>'}async function setStock(id,v){try{await apiFetch('/operacoes/admin/stock/'+id,{method:'PUT',body:JSON.stringify({stock:Number(v)})});load()}catch(e){alert(e.message)}}async function setVar(id,v){try{await apiFetch('/operacoes/admin/stock/variante/'+id,{method:'PUT',body:JSON.stringify({stock:Number(v)})});load()}catch(e){alert(e.message)}}document.getElementById('sync').onclick=async()=>{try{const r=await apiFetch('/produtos/admin/sincronizar-catalogo',{method:'POST'});document.getElementById('msg').textContent=`${r.resultados.filter(x=>x.ok).length}/${r.total} sincronizados.`;load()}catch(e){document.getElementById('msg').textContent=e.message}};load().catch(e=>document.getElementById('rows').innerHTML=`<tr><td colspan="5">${esc(e.message)}</td></tr>`);
